function OverviewBalanceMap({dimensions,nodes,darkMode,onSelect}) {
  const defs=[
    {id:"social",label:"Social",short:"SOC",color:"#22c55e"},
    {id:"health",label:"Health",short:"HLT",color:"#ef4444"},
    {id:"mind",label:"Mind",short:"MND",color:"#14b8a6"},
    {id:"knowledge",label:"Knowledge",short:"LRN",color:"#3b82f6"},
    {id:"creativity",label:"Creativity",short:"CRT",color:"#9333ea"},
    {id:"growth",label:"Growth",short:"GRW",color:"#f97316"},
    {id:"purpose",label:"Purpose",short:"PUR",color:"#eab308"},
    {id:"rest",label:"Rest",short:"RST",color:"#06b6d4"},
    {id:"security",label:"Security",short:"SEC",color:"#64748b"}
   ];
  const cx=210,cy=210;
  const points=defs.map((def,index)=>{
    const dim=dimensions[def.id]||{};
    const score=Math.max(0,Math.min(100,Math.round((dim.health??.5)*100)));
    const target=Math.max(1,Number(dim.weeklyTarget)||1);
    const effort=Math.max(0,Number(dim.weeklyScore)||0);
    const load=effort/target;
    const over=load>1.75;
    const distance=62+(score/100)*108+(over?16:0);
    const angle=(-90+index*(360/defs.length))*Math.PI/180;
    const status=over?"May be crowding out balance":score<35?"Needs focus":score<65?"Building":"Healthy";
    return {...def,score,load,over,distance,angle,x:cx+Math.cos(angle)*distance,y:cy+Math.sin(angle)*distance,status};
  });
  const overall=Math.round(points.reduce((sum,p)=>sum+(p.over?Math.max(0,p.score-(p.load-1.75)*14):p.score),0)/points.length);
  const weakest=[...points].sort((a,b)=>a.score-b.score)[0];
  const me=nodes.find(n=>n.id==="me");
  const card=darkMode?"#111827":"white",text=darkMode?"#e2e8f0":"#1e293b",sub=darkMode?"#94a3b8":"#64748b";
  return <div style={{maxWidth:760,margin:"0 auto",color:text}}>
    <section style={{background:card,borderRadius:18,padding:12,border:`1px solid ${darkMode?"#334155":"#e2e8f0"}`,boxShadow:"0 10px 28px rgba(15,23,42,.12)"}}>
      <div style={{display:"flex",alignItems:"center",gap:10,marginBottom:2}}>
        <span style={{fontSize:26,color:"#d4a017"}}>★</span>
        <div><div style={{fontWeight:900,fontSize:18}}>Overall balance</div><div style={{fontSize:10,color:sub}}>Further out means stronger. A dark, muted endpoint can indicate possible over-focus.</div></div>
        <div style={{marginLeft:"auto",fontSize:24,fontWeight:900,color:"#d4a017"}}>{overall}</div>
      </div>
      <svg viewBox="0 0 420 420" style={{display:"block",width:"100%",maxHeight:"62vh",minHeight:340}}>
        <defs><clipPath id="overview-me-clip"><circle cx={cx} cy={cy} r="27"/></clipPath></defs>
        {[55,95,135,175].map((r,i)=><circle key={r} cx={cx} cy={cy} r={r} fill="none" stroke={darkMode?"#475569":"#94a3b8"} strokeWidth={4+i*.5} opacity={.25+i*.08}/>)}
        {points.map(p=><line key={"line-"+p.id} x1={cx} y1={cy} x2={p.x} y2={p.y} stroke={p.color} strokeWidth="2.5" opacity={.25+p.score/190}/>)}
        <circle cx={cx} cy={cy} r="32" fill={darkMode?"#1e293b":"white"} stroke="#d4a017" strokeWidth="4"/>
        {me?.img?<image href={me.img} x={cx-27} y={cy-27} width="54" height="54" preserveAspectRatio="xMidYMid slice" clipPath="url(#overview-me-clip)"/>:<text x={cx} y={cy+5} textAnchor="middle" fontSize="13" fontWeight="900" fill={text}>ME</text>}
        {points.map(p=>{
          const saturation=p.over?38:Math.max(52,68+p.score*.3);
          const brightness=p.over?55:78+p.score*.18;
          const labelRadius=p.distance+14,lx=cx+Math.cos(p.angle)*labelRadius,ly=cy+Math.sin(p.angle)*labelRadius;
          const anchor=Math.cos(p.angle)>.25?"start":Math.cos(p.angle)<-.25?"end":"middle";
          return <g key={p.id} onClick={()=>onSelect(p.id)} style={{cursor:"pointer"}}>
            <circle cx={p.x} cy={p.y} r="7" fill={p.color} stroke={darkMode?"#0f172a":"white"} strokeWidth="2" style={{filter:`saturate(${saturation}%) brightness(${brightness}%)`}}/>
            <text x={lx} y={ly-1} textAnchor={anchor} fontSize="7.5" fontWeight="900" fill={p.color}>{p.short}</text>
            <title>{p.label}: {p.score}/100 · {p.status}</title>
          </g>
        })}
      </svg>
      <div style={{padding:10,borderRadius:12,background:weakest.color+"18",border:`1px solid ${weakest.color}66`,fontSize:12}}>
        <strong style={{color:weakest.color}}>Focus next: {weakest.label}</strong><span style={{color:sub}}> · {weakest.status} ({weakest.score})</span>
      </div>
    </section>
  </div>
}
